            return ActError();
        }
        int n = emon.Port.CellsLen(p.Srt);
        if (n == 0) {
            p.Err = PeBadRecord();
            emon.Port.TextAscii(p.Msg, "the unit asked for requests and wrote none");
            return ActError();
        }
        p.Rounds += 1;
        if (p.Rounds > p.MaxRounds) {
            return PlLimit(p, PeMaxRounds(), p.MaxRounds, p.Rounds);
        }
        p.Requests += n;
        p.Round = p.Rounds - 1;
        p.Outk = 2;
        return ActRequests();
    }
    public static int PlAfter(emon.Planctx.Plan p, int status) {
        // The unit answered `status` (`us-*`): what the host does next (`act-*`).
