            p.FetchRounds += 1;
            if (p.FetchRound > p.FetchLimit) {
                return PlLimit(p, PeFetchRounds(), p.FetchLimit, p.FetchRound);
            }
            return ActMiss();
        }
        if (status == Plan.UsDone()) {
            if (emon.Port.CellsLen(p.Rq) != 0) {
                p.Err = PeBadRecord();
                emon.Port.TextAscii(p.Msg, "the unit is done and left requests");
                return ActError();
            }
            return ActDone();
        }
        if (status == Plan.UsRequests()) {
            return PlRequests(p);
        }
        p.Err = PeUnitFailed();
        p.ErrActual = status;
        emon.Port.TextAscii(p.Msg, "status ");
        emon.Port.TextI32(p.Msg, status);
        return ActError();
    }
