    public static int PlFetch(emon.Planctx.Plan p) {
        // The ranges the host put in `cand` (`input offset length` triples) become the round's `bytes` requests `[6 4 -n input offset length]`, ids
        // -1, -2, ... for the whole unit. None is `need-bytes-stalled`: the unit missed and the source reports nothing missed.
        int n = emon.Port.CellsLen(p.Cand);
        int i = 0;
        emon.Port.CellsDrop(p.Reqs, 0);
        emon.Port.CellsDrop(p.Got, 0);
        if (n == 0) {
            p.Err = PeStalled();
            emon.Port.TextAscii(p.Msg, "the unit missed and the source reports nothing missed");
            return ActError();
        }
        while (i < n) {
            p.BytesRequests += 1;
            int input = emon.Port.CellsAt(p.Cand, i);
            int off = emon.Port.CellsAt(p.Cand, i + 1);
            int ln = emon.Port.CellsAt(p.Cand, i + 2);
            Plan.RqBytes(p.Reqs, 0 - p.BytesRequests, input, off, ln);
            i += 3;
        }
        emon.Port.CellsDrop(p.Cand, 0);
        p.Outk = 1;
        return ActFetch();
    }
    public static int PlOffer(emon.Planctx.Plan p) {
        // The answer in `cur` (a whole record) joins the round: refused (`act-error`, `bad-record`) when it is malformed, answers a request the round did
        // not make or whose kind it does not have, or answers one already answered. Answers 0 when taken.
        int n = emon.Port.CellsLen(p.Cur);
        int declared = 0;
        if (n > 0) {
            declared = emon.Port.CellsAt(p.Cur, 0);
        }
        if ((n < 4) || (declared != n)) {
            p.Err = PeBadRecord();
            emon.Port.TextAscii(p.Msg, "an answer has length ");
            emon.Port.TextI32(p.Msg, declared);
            emon.Port.TextAscii(p.Msg, " in a record of ");
            emon.Port.TextI32(p.Msg, n);
            return ActError();
        }
        int kind = emon.Port.CellsAt(p.Cur, 1);
        int id = emon.Port.CellsAt(p.Cur, 2);
        int at = Plan.RecFind(p.Reqs, id);
        if ((at < 0) || ((emon.Port.CellsAt(p.Reqs, at + 1) != kind) || (Plan.RecFind(p.Got, id) >= 0))) {
            p.Err = PeBadRecord();
            emon.Port.TextAscii(p.Msg, "an answer for request ");
            emon.Port.TextI32(p.Msg, id);
            emon.Port.TextAscii(p.Msg, " (kind ");
            emon.Port.TextI32(p.Msg, kind);
            emon.Port.TextAscii(p.Msg, ") answers nothing asked");
            return ActError();
        }
        PlCopy(p.Got, p.Cur, 0, n);
        return 0;
    }
    public static int PlHas(emon.Planctx.Plan p, int id) {
